import React, { useEffect } from 'react';
import { HashRouter, Routes, Route, useLocation } from 'react-router-dom';
import { useTranslation } from 'react-i18next';
import Header from './components/Header';
import Footer from './components/Footer';
import HomePage from './pages/HomePage';
import AboutPage from './pages/AboutPage';
import ServicesPage from './pages/ServicesPage';
import TeamPage from './pages/TeamPage';
import ContactPage from './pages/ContactPage';
import PrivacyPolicyPage from './pages/PrivacyPolicyPage';
import TermsPage from './pages/TermsPage';
import AdminPanelPage from './pages/AdminPanelPage';

const PageMetadataUpdater: React.FC = () => {
  const location = useLocation();
  const { t, i18n } = useTranslation();

  useEffect(() => {
    let titleKey = 'meta.home.title';
    let descKey = 'meta.home.description';

    switch (location.pathname) {
      case '/about':
        titleKey = 'meta.about.title';
        descKey = 'meta.about.description';
        break;
      case '/services':
        titleKey = 'meta.services.title';
        descKey = 'meta.services.description';
        break;
      case '/team':
        titleKey = 'meta.team.title';
        descKey = 'meta.team.description';
        break;
      case '/contact':
        titleKey = 'meta.contact.title';
        descKey = 'meta.contact.description';
        break;
      case '/privacy-policy':
        titleKey = 'meta.privacy.title';
        descKey = 'meta.privacy.description';
        break;
      case '/terms-and-conditions':
        titleKey = 'meta.terms.title';
        descKey = 'meta.terms.description';
        break;
      case '/admin':
        titleKey = 'meta.admin.title';
        descKey = 'meta.admin.description';
        break;
      case '/':
      default:
        titleKey = 'meta.home.title';
        descKey = 'meta.home.description';
        break;
    }

    document.title = t(titleKey);
    document.querySelector('meta[name="description"]')?.setAttribute('content', t(descKey));
    document.documentElement.lang = i18n.language;

  }, [location, i18n.language, t]);

  return null;
}

const App: React.FC = () => {
  return (
    <HashRouter>
      <PageMetadataUpdater />
      <div className="bg-brand-dark text-brand-light font-sans antialiased">
        <Header />
        <main>
          <Routes>
            <Route path="/" element={<HomePage />} />
            <Route path="/about" element={<AboutPage />} />
            <Route path="/services" element={<ServicesPage />} />
            <Route path="/team" element={<TeamPage />} />
