import React from 'react';
import { useParams, Link } from 'react-router-dom';
import { BLOG_POSTS } from '../constants';
import Image from '../components/Image';

const BlogPostPage: React.FC = () => {
    const { slug } = useParams<{ slug: string }>();
    const post = BLOG_POSTS.find(p => p.slug === slug);

    if (!post) {
        return (
            <div className="py-40 text-center">
                <h1 className="text-4xl font-bold text-white">404 - Post Not Found</h1>
                <p className="mt-4 text-brand-slate">The blog post you are looking for does not exist.</p>
                <Link to="/blog" className="mt-8 inline-block px-6 py-3 text-lg font-semibold text-white bg-brand-blue rounded-md hover:bg-opacity-80">
                    Back to Blog
                </Link>
            </div>
        );
    }

    const formattedContentEn = post.contentEn
      .split('\n\n')
      .map(paragraph => {
        // Handle bullet points
        if (paragraph.startsWith('*   ')) {
          const listItems = paragraph.split('\n').map(item => `<li>${item.substring(4)}</li>`).join('');
          return `<ul>${listItems}</ul>`;
        }
        // Handle headings
        if (paragraph.startsWith('### ')) {
            return `<h3>${paragraph.substring(4)}</h3>`;
        }
        return `<p>${paragraph.replace(/\n/g, '<br />')}</p>`;
      })
      .join('');

    // Using English content for this example. A full i18n solution would be needed for language switching.
    return (
        <div className="animate-fade-in-up">
