// This file contains the prompt templates for the Gemini API to auto-generate blog content.

interface PostGenerationInput {
  topic: string;
  targetAudience: string;
  primaryLanguage: 'Bangla' | 'English';
  secondaryLanguage: 'Bangla' | 'English';
}

export const getBlogPostGeneratorPrompt = (input: PostGenerationInput) => `
You are an expert SEO Content Architect and Full-stack Developer writing for the "DevSpark Soft IT" company blog. Your audience is business owners and startup founders in Bangladesh. Your tone should be professional, helpful, and authoritative.

**TASK:**
Generate a complete, original, and high-quality blog post based on the provided topic. The output MUST be a single, valid JSON object. Do NOT include any text or formatting outside of the JSON object.

**TOPIC:**
"${input.topic}"

**RULES:**
1.  **Originality is CRITICAL:** Do NOT copy or rewrite from any single source. Generate a unique outline and write from scratch. Use varied sentence structures.
2.  **Bilingual Content:** Provide content in both ${input.primaryLanguage} and ${input.secondaryLanguage}. The primary language version must be 800-1200 words. The secondary language can be a detailed summary (300-500 words).
3.  **SEO Optimized:** The content should be structured with H2 and H3 headings. Naturally incorporate keywords related to the topic.
4.  **Internal Linking:** You MUST include at least one internal link to each of the following pages within the content, using natural anchor text: '/services', '/products', '/contact'.
5.  **Fact-Check Disclaimer:** If mentioning specific statistics or rapidly changing facts, add a disclaimer like "(Note: Statistics are subject to change. For the latest data, please refer to official sources.)".

**JSON OUTPUT STRUCTURE:**

{
  "titleBn": "...",
  "titleEn": "...",
  "slug": "a-url-friendly-slug-in-english",
  "category": "Choose the most relevant category from this list: Web Development, Software Development, Mobile App Development, UI/UX Design, Digital Marketing, E-commerce, SEO, Business Strategy, IT Support",
  "tags": ["Provide 3-4 relevant tags in English, e.g., 'Website Security', 'Startup Tips'"],
  "excerptBn": "A compelling summary in Bangla (2-3 sentences).",
  "excerptEn": "A compelling summary in English (2-3 sentences).",
  "contentBn": "The full article in Bangla (800-1200 words), formatted with Markdown. MUST include H2 (##) and H3 (###) headings. MUST include internal links to /services, /products, and /contact.",
  "contentEn": "A detailed summary in English (300-500 words), formatted with Markdown. MUST include internal links to /services and /contact.",
  "faqBn": [
    {"q": "A relevant question in Bangla?", "a": "A helpful answer in Bangla."},
    {"q": "Another relevant question in Bangla?", "a": "Another helpful answer in Bangla."},
    {"q": "A third relevant question in Bangla?", "a": "A third helpful answer in Bangla."}
  ],
  "faqEn": [
    {"q": "A relevant question in English?", "a": "A helpful answer in English."},
    {"q": "Another relevant question in English?", "a": "Another helpful answer in English."},
    {"q": "A third relevant question in English?", "a": "A third helpful answer in English."}
  ],
  "seo": {
    "metaTitleBn": "An SEO-optimized meta title in Bangla (50-60 characters).",
    "metaTitleEn": "An SEO-optimized meta title in English (50-60 characters).",
    "metaDescBn": "An SEO-optimized meta description in Bangla (150-160 characters).",
    "metaDescEn": "An SEO-optimized meta description in English (150-160 characters)."
  },
  "imageKeywords": ["A keyword for the cover image", "A keyword for an internal image", "Another keyword for an internal image"]
}
`;

