const BlogPage: React.FC = () => {
    const [searchTerm, setSearchTerm] = useState('');
    const [selectedCategory, setSelectedCategory] = useState<string>('All');
    const [selectedTag, setSelectedTag] = useState<string>('All');
    const [currentPage, setCurrentPage] = useState(1);
    const postsPerPage = 6;

    const filteredPosts = useMemo(() => {
        return BLOG_POSTS
            .filter(post => post.titleEn.toLowerCase().includes(searchTerm.toLowerCase()))
            .filter(post => selectedCategory === 'All' || post.category.name === selectedCategory)
            .filter(post => selectedTag === 'All' || post.tags.some(t => t.name === selectedTag));
    }, [searchTerm, selectedCategory, selectedTag]);

    const indexOfLastPost = currentPage * postsPerPage;
    const indexOfFirstPost = indexOfLastPost - postsPerPage;
    const currentPosts = filteredPosts.slice(indexOfFirstPost, indexOfLastPost);

    const featuredPost = BLOG_POSTS[0];

  return (
    <div className="animate-fade-in-up">
      <PageHeader title="DevSpark Insights" subtitle="Your expert source for tech trends, business strategies, and digital innovation in Bangladesh." />

      <section className="py-20 bg-gray-900/50">
        <div className="container mx-auto px-4 sm:px-6 lg:px-8">
            <FeaturedPost post={featuredPost} />
        </div>
      </section>

      <section className="py-20 bg-brand-dark">
        <div className="container mx-auto px-4 sm:px-6 lg:px-8">
          {/* Filters and Search */}
          <div className="mb-12">
            <div className="grid md:grid-cols-3 gap-4 items-center">
                <div className="md:col-span-1">
                    <SearchBar onSearch={setSearchTerm} />
                </div>
                <div className="md:col-span-2 flex flex-wrap gap-2 justify-start md:justify-end">
                    <select onChange={(e) => {setSelectedCategory(e.target.value); setCurrentPage(1);}} className="bg-gray-800/60 text-brand-slate p-2 rounded-md">
                        <option value="All">All Categories</option>
                        {BLOG_CATEGORIES.map(cat => <option key={cat.id} value={cat.name}>{cat.name}</option>)}
                    </select>
                     <select onChange={(e) => {setSelectedTag(e.target.value); setCurrentPage(1);}} className="bg-gray-800/60 text-brand-slate p-2 rounded-md">
                        <option value="All">All Tags</option>
                        {BLOG_TAGS.map(tag => <option key={tag.id} value={tag.name}>{tag.name}</option>)}
                    </select>
                </div>
            </div>
          </div>

          {/* Posts Grid */}
          {currentPosts.length > 0 ? (
            <>
              <div className="grid md:grid-cols-2 lg:grid-cols-3 gap-8">
                {currentPosts.map((post, index) => (
                  <div key={post.id} className="animate-fade-in-up" style={{ animationDelay: `${index * 0.1}s` }}>
                    <BlogPostCard post={post} />
                  </div>
                ))}
              </div>
              <Pagination
                currentPage={currentPage}
                totalPosts={filteredPosts.length}
                postsPerPage={postsPerPage}
                onPageChange={setCurrentPage}
              />
            </>
          ) : (
            <div className="text-center py-20">
                <h2 className="text-2xl font-bold text-white">No Posts Found</h2>
                <p className="mt-4 text-brand-slate">Try adjusting your search or filter criteria.</p>
            </div>
          )}
        </div>
      </section>
    </div>
  );
};

export default BlogPage;

