import React, { useEffect, useState } from 'react';

interface TocItem {
  level: number;
  text: string;
  id: string;
}

interface TableOfContentsProps {
  content: string;
}

const TableOfContents: React.FC<TableOfContentsProps> = ({ content }) => {
  const [headings, setHeadings] = useState<TocItem[]>([]);

  useEffect(() => {
    const extractedHeadings: TocItem[] = [];
    // This regex is a simple approximation. A more robust solution might use a Markdown parser.
    const headingRegex = /<h([2-3])[^>]*>(.*?)<\/h\1>/g;

    // Fallback regex for markdown if HTML isn't yet rendered (though the prompt suggests HTML)
    const markdownRegex = /^(##|###)\s(.*)/gm;

    // This is a simplified example. In a real app with a proper markdown-to-html library,
    // you would get structured data instead of parsing raw strings.
    const lines = content.split('\n');
    lines.forEach(line => {
        if (line.startsWith('## ')) {
            const text = line.substring(3);
            extractedHeadings.push({
                level: 2,
                text: text,
                id: text.toLowerCase().replace(/\s+/g, '-').replace(/[^\w-]+/g, '')
            });
        } else if (line.startsWith('### ')) {
            const text = line.substring(4);
             extractedHeadings.push({
                level: 3,
                text: text,
                id: text.toLowerCase().replace(/\s+/g, '-').replace(/[^\w-]+/g, '')
            });
        }
    });

    setHeadings(extractedHeadings);
  }, [content]);

  if (headings.length === 0) {
    return <p className="text-brand-slate text-sm">No headings found in this article.</p>;
  }

  return (
    <ul className="space-y-2">
      {headings.map((heading) => (
        <li key={heading.id} style={{ marginLeft: `${(heading.level - 2) * 1}rem` }}>
          <a
            href={`#${heading.id}`}
            className="text-brand-slate hover:text-brand-orange transition-colors duration-200 text-sm"
            onClick={(e) => {
              // Smooth scroll - In a real app, might need a more robust library
              e.preventDefault();
              document.getElementById(heading.id)?.scrollIntoView({ behavior: 'smooth' });
            }}
          >
            {heading.text}
          </a>
        </li>
      ))}
    </ul>
  );
};

export default TableOfContents;

